<?php /** 赛事业务视图；负责人：王乐之（2411302）；AI辅助开发。 */ use yii\helpers\{Html,Url};$this->title='比赛'; ?>
<h1>比赛赛程</h1><form action="<?= Html::encode(\yii\helpers\Url::to(['index'])) ?>" method="get" class="wc-filters"><input name="q" placeholder="搜索球队" value="<?= Html::encode(Yii::$app->request->get('q','')) ?>"><input aria-label="比赛日期" type="date" name="date" value="<?= Html::encode(Yii::$app->request->get('date','')) ?>"><select aria-label="世界杯届次" name="tournament_id"><option value="">全部届次</option><?php foreach($tournaments as $x):?><option value="<?= $x->id ?>" <?= Yii::$app->request->get('tournament_id')==$x->id?'selected':'' ?>><?= Html::encode($x->name) ?></option><?php endforeach ?></select><select aria-label="比赛阶段" name="stage_id"><option value="">全部阶段</option><?php foreach($stages as $x):?><option value="<?= $x->id ?>" <?= Yii::$app->request->get('stage_id')==$x->id?'selected':'' ?>><?= Html::encode($x->name) ?></option><?php endforeach ?></select><select aria-label="球队" name="team_id"><option value="">全部球队</option><?php foreach($teams as $x):?><option value="<?= $x->id ?>" <?= Yii::$app->request->get('team_id')==$x->id?'selected':'' ?>><?= Html::encode($x->name) ?></option><?php endforeach ?></select><select aria-label="比赛排序" name="sort"><option value="new">最近优先</option><option value="old" <?= Yii::$app->request->get('sort')==='old'?'selected':'' ?>>最早优先</option></select><button>筛选</button></form>
<?php if(!$matches):?><p class="empty">没有符合条件的比赛。</p><?php endif ?><div class="grid"><?php foreach($matches as $m):?><article class="card"><small><?= Html::encode($m->stage->name) ?> · <?= Html::encode((new DateTimeImmutable($m->kicks_off_at,new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('Asia/Shanghai'))->format('Y-m-d H:i')) ?> 北京时间</small><h2><?= Html::a(Html::encode($m->homeTeam->name).' '.((int)$m->normal_home+(int)$m->extra_home).' : '.((int)$m->normal_away+(int)$m->extra_away).' '.Html::encode($m->awayTeam->name),['view','id'=>$m->id]) ?></h2><p><?= Html::encode($m->stadium->name) ?></p></article><?php endforeach ?></div><?= yii\widgets\LinkPager::widget(['pagination'=>$pages]) ?>
